 fashionSamples.forEach(p=>{if(!productsData.some(x=>x.id===p.id))productsData.push(p);});
 const labels=['New born','Jabala','Rompers and body suite','Infants','Boy','Girl'];
 const ages=[{label:'0–3 months',min:0,max:3},{label:'3–6 months',min:3,max:6},{label:'6–12 months',min:6,max:12},{label:'1–2 years',min:12,max:24},{label:'2–3 years',min:24,max:36},{label:'3+ years',min:36,max:Infinity}];
