 const fashionPage=document.createElement('section');fashionPage.id='bo-fashion-page';fashionPage.className='hidden';fashionPage.innerHTML='<div class="section" id="bo-fashion-page-content"><div class="section-head"><span class="eyebrow">Little Wardrobes</span><h2 id="bo-fashion-page-heading">Shop Fashion</h2></div></div>';
 document.getElementById('home-page').insertAdjacentElement('afterend',fashionPage);
 const pageContent=document.getElementById('bo-fashion-page-content');[nav,grid,results].forEach(node=>pageContent.appendChild(node));
 const previousShowSection=window.showSection;
 window.showSection=function(id){fashionPage.classList.toggle('hidden',id!=='bo-fashion-page');return previousShowSection.apply(this,arguments);};
 function page(){window.showSection('bo-fashion-page');}
 function route(view,age,category){try{history.pushState({boFashion:true,view,age,category},'',location.pathname+location.search+'#fashion-'+(age===null?'ages':age+'-'+view+(category===undefined?'':'-'+category)));}catch(e){}}
 let selectedAge=null;
 function clothes(){return productsData.filter(p=>p.category==='Clothing'&&!p.catalogHidden);}
 function text(p){return [p.name,p.subcategory,p.fashionCategory,p.gender].filter(Boolean).join(' ').toLowerCase();}
 function range(p){
  if(Number.isFinite(p.ageMinMonths)&&Number.isFinite(p.ageMaxMonths))return [p.ageMinMonths,p.ageMaxMonths];
  const t=String(p.ageGroup||p.age||p.subcategory||'').toLowerCase();
  const m=t.match(/(\d+)\s*[–-]\s*(\d+)\s*(years?|yrs?|months?|mos?)?/);
  if(m){const scale=/year|yr/.test(m[3]||'')?12:1;return [+m[1]*scale,+m[2]*scale];}
  const plus=t.match(/(\d+)\s*\+\s*(years?|yrs?|months?)?/);
  if(plus)return [+plus[1]*(/month/.test(plus[2]||'')?1:12),Infinity];
  if(/newborn|new born/.test(t))return [0,3];
  if(/infant/.test(t))return [0,12];
  if(/toddler/.test(t))return [12,36];
  return null;
 }
 function ageFits(p,index=selectedAge){if(p.fashionSample)return p.fashionAgeIndex===index;const r=range(p),a=ages[index];return !!r&&r[0]<a.max&&r[1]>a.min;}
 function categoryFits(p,label){if(p.fashionSample)return p.fashionCategory===label;const t=text(p);return ({'New born':/newborn|new born/,'Jabala':/jabala|jhabla|jabla/,'Rompers and body suite':/romper|bodysuit|body suit|playsuit|onesie/,'Infants':/infant|newborn|new born|0[–-]1/,'Boy':/\bboy\b|\bboys\b|unisex/,'Girl':/\bgirl\b|\bgirls\b|dress|unisex/})[label].test(t);}
 function card(label,image,attribute,index){return '<button type="button" class="bo-fashion-tile" '+attribute+'="'+index+'"><img loading="lazy" src="'+escapeHtml(image)+'" alt="'+escapeHtml(label)+'"><span>'+label+'</span></button>';}
 function fallback(){return clothes()[0]?.image||categoriesData.find(c=>c.name==='Clothing')?.img||'';}
 function showAges(push=true){if(push)route('ages',null);window.showSection('home-page');selectedAge=null;ageGrid.hidden=false;grid.hidden=true;results.hidden=true;nav.hidden=true;ageGrid.innerHTML=ages.map((a,i)=>card(a.label,ageCovers[i],'data-fashion-age',i)).join('');}
 function showCategories(index,push=true){if(push)route('categories',index);page();document.getElementById('bo-fashion-page-heading').textContent='Fashion · '+ages[index].label;selectedAge=index;ageGrid.hidden=false;grid.hidden=false;results.hidden=true;nav.hidden=false;document.getElementById('bo-fashion-selected-age').textContent=ages[index].label;grid.innerHTML=labels.map((label,i)=>card(label,clothes().find(p=>p.fashionSample&&categoryFits(p,label))?.image||fallback(),'data-fashion',i)).join('');}
 function showProducts(index,push=true){if(push)route('products',selectedAge,index);page();const label=labels[index],list=clothes().filter(p=>ageFits(p)&&categoryFits(p,label));grid.hidden=true;results.hidden=false;document.getElementById('bo-fashion-title').textContent=label+' · '+ages[selectedAge].label;document.getElementById('bo-fashion-count').textContent=list.length?list.length+' products':'No products are available for this category and age yet. Please try another age or category.';document.getElementById('bo-fashion-products').innerHTML=list.map(productCard).join('');}
 ageGrid.addEventListener('click',e=>{const card=e.target.closest('[data-fashion-age]');if(card)showCategories(Number(card.dataset.fashionAge));});
 grid.addEventListener('click',e=>{const card=e.target.closest('[data-fashion]');if(card)showProducts(Number(card.dataset.fashion));});
 document.getElementById('bo-fashion-back').addEventListener('click',()=>showCategories(selectedAge));
 document.getElementById('bo-fashion-ages-back').addEventListener('click',()=>showAges());
 window.addEventListener('popstate',e=>{const st=e.state;if(!st?.boFashion)return;if(st.view==='ages')showAges(false);else if(st.view==='categories')showCategories(st.age,false);else{selectedAge=st.age;showProducts(st.category,false);}});
 showAges(false);
